function validate([word, k]) {
  if (typeof word !== 'string' || word.length < 1 || word.length > 50) return 'word needs 1 to 50 characters.';
  if (!/^[a-z]+$/.test(word)) return 'word may contain only lowercase letters.';
  if (!Number.isInteger(k) || k < 1 || k > word.length) return 'k is between 1 and the length of word.';
  return null;
}

