function generate(rand, size) {
  const n = size === 'large' ? 40 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 10);
  const letters = 'abc'.slice(0, 1 + Math.floor(rand() * 3));
  const pick = () => letters[Math.floor(rand() * letters.length)];
  // Repeat a short block with a little noise so suffixes often match prefixes.
  const period = 1 + Math.floor(rand() * Math.min(n, size === 'large' ? 12 : 4));
  const block = Array.from({ length: period }, pick);
  let word = '';
  for (let i = 0; i < n; i++) word += rand() < 0.1 ? pick() : block[i % period];
  let k = 1 + Math.floor(rand() * n);
  if (rand() < 0.4) k = Math.min(n, period * (1 + Math.floor(rand() * 3)));
  return [word, k];
}
